// typed_a7_check_rt.h: round A7's differential check (a7_typed_check.cpp, generated by tools/typed_lift2.py --check-tu;
// docs/decomp_a7.md). Only the check translation unit and the offline harness (tools/a7_harness.cpp) include it. Made from
// typed_a6_check_rt.h by build/a7w/mkcheck7.py (the same check in its own namespace a7ck, the "[a7]" line), plus:
//   - the printf-family stubs (printf, iosJumpRecoverPoint, vsprintf, sceWrite): both legs run the same check version on their
//     logged memory (a7x below; the reference's call through refExt): printf / iosJumpRecoverPoint a value of the format
//     string's bytes, the eight argument words and the first eight stack words above sp + 0x10 (read from the leg's memory:
//     what the caller passed, the outgoing argument slots of its guest frame); vsprintf the format string copied into the
//     destination with its length returned; sceWrite no write (the size, 0 or -1 as the core would for a buffer in / out of
//     RAM). So the check compares the callers (what they pass and how they use the result); the shipped typed stubs run the
//     stubs' own cores (typed_a7_ext.h), the same code as the stubs. A string past main RAM gives the check up;
//   - a typed callee's extra outputs consumed by its typed caller need nothing here: the reference legs run the callees'
//     lifted texts on the context, the typed leg the typed callers; the outputs are compared as before.
#pragma once

#define A3CK_NS a7ck
#define A3CK_LABEL "[a7]"
#define A4_CHECK_TU 1
#define A5_CHECK_TU 1
#define A6_CHECK_TU 1
#define A7_CHECK_TU 1
#include "typed_a3_check_rt.h"
#include "typed_a5_rt.h"
#include "typed_a6_rt.h"
#include "typed_a7_rt.h"
#include "typed_a7_nchk.h"

#include <cstring>
#include <exception>

#if !defined(A7_OFFLINE)
#include "sotc_decomp.h"
namespace decomp_sema
{
    int32_t getThreadIdTyped(uint8_t *rdram, PS2Runtime *runtime);
}
#endif

namespace a7ck
{
    extern const uint32_t kRelocs[][2];
    extern const uint32_t kRelocCount;
    bool nativeLeg(uint32_t addr, uint8_t *rdram, const R5900Context *ctx, PS2Runtime *runtime, uint64_t &v0, float &f0, int &kind);

    // ---- break
    inline uint32_t g_brkN[2] = {0, 0}, g_brkFirst[2] = {0, 0}, g_brkLast[2] = {0, 0};
    inline uint64_t g_brkDiffer = 0, g_brks = 0;
    inline void brkReset()
    {
        for (int c = 0; c < 2; ++c)
            g_brkN[c] = g_brkFirst[c] = g_brkLast[c] = 0;
    }
    inline void legBrk(uint32_t site)
    {
        const int c = st().cur;
        if (g_brkN[c]++ == 0u)
            g_brkFirst[c] = site;
        g_brkLast[c] = site;
    }
    inline bool brkDiffer()
    {
        g_brks += g_brkN[1];
        const bool d = g_brkN[0] != g_brkN[1] || (g_brkN[0] && (g_brkFirst[0] != g_brkFirst[1] || g_brkLast[0] != g_brkLast[1]));
        g_brkDiffer += d;
        return d;
    }

    // ---- the typed runtime stubs on the leg's logged memory
    inline uint64_t g_extCalls = 0, g_extGiveUp = 0;
    inline bool inRam(uint32_t a, uint32_t n) { return a < PS2_RAM_SIZE && n <= PS2_RAM_SIZE - a; }
    inline void giveUp()
    {
        ++g_extGiveUp;
        st().ovf = true;
    }
    // a string from the leg's memory into buf (false: past main RAM or longer than the buffer)
    inline bool readStr(uint32_t a, char *buf, uint32_t cap, uint32_t &len)
    {
        for (len = 0; len < cap; ++len)
        {
            if (a + len >= PS2_RAM_SIZE)
                return false;
            buf[len] = static_cast<char>(rd<uint8_t>(a + len));
            if (!buf[len])
                return true;
        }
        return false;
    }
    inline bool leavesOn()
    {
#if defined(A7_OFFLINE)
        return true;
#else
        return sotc_decomp::leavesOn();
#endif
    }
    namespace a6x
    {
        inline uint32_t clampSize(uint32_t n) { return n <= PS2_RAM_SIZE ? n : PS2_RAM_SIZE; }
        inline uint64_t memset(uint8_t *, PS2Runtime *, uint64_t a0, uint32_t a1, uint32_t a2, uint64_t &io_h2, uint64_t io_h4)
        {
            ++g_extCalls;
            const uint32_t d = static_cast<uint32_t>(a0), n = clampSize(a2);
            if (n && !inRam(d, n))
                giveUp();
            else
                for (uint32_t i = 0; i < n; ++i)
                    wr<uint8_t>(d + i, static_cast<uint8_t>(a1));
            io_h2 = io_h4;
            return a0;
        }
        inline uint64_t memcpy(uint8_t *, PS2Runtime *, uint64_t a0, uint32_t a1, uint32_t a2, uint64_t &io_h2, uint64_t io_h4)
        {
            ++g_extCalls;
            uint32_t d = static_cast<uint32_t>(a0), s = a1, n = clampSize(a2);
            if (n && (!inRam(d, n) || !inRam(s, n)))
                giveUp();
            else if (n <= 512u)
            {
                // the stub's inline copy (smallCopy): 16, 8, 4 bytes at a time through a temporary, then bytes, forward
                uint8_t t[16];
                for (; n >= 16u; n -= 16u, d += 16u, s += 16u)
                {
                    for (int k = 0; k < 16; ++k)
                        t[k] = rd<uint8_t>(s + k);
                    for (int k = 0; k < 16; ++k)
                        wr<uint8_t>(d + k, t[k]);
                }
                for (uint32_t step : {8u, 4u})
                    if (n >= step)
                    {
                        for (uint32_t k = 0; k < step; ++k)
                            t[k] = rd<uint8_t>(s + k);
                        for (uint32_t k = 0; k < step; ++k)
                            wr<uint8_t>(d + k, t[k]);
                        n -= step, d += step, s += step;
                    }
                for (; n; --n)
                    wr<uint8_t>(d++, rd<uint8_t>(s++));
            }
            else if (d < s + n && s < d + n)
                giveUp(); // ::memcpy over an overlap: the host's choice
            else
                for (uint32_t i = 0; i < n; ++i)
                    wr<uint8_t>(d + i, rd<uint8_t>(s + i));
            io_h2 = io_h4;
            return a0;
        }
        inline uint64_t strcpy(uint8_t *, PS2Runtime *, uint64_t a0, uint32_t a1, uint64_t &io_h2, uint64_t io_h4)
        {
            ++g_extCalls;
            char buf[4096];
            uint32_t len = 0;
            const uint32_t d = static_cast<uint32_t>(a0);
            if (!readStr(a1, buf, sizeof(buf), len) || !inRam(d, len + 1u) || (d < a1 + len + 1u && a1 < d + len + 1u))
                giveUp();
            else
                for (uint32_t i = 0; i <= len; ++i)
                    wr<uint8_t>(d + i, static_cast<uint8_t>(buf[i]));
            io_h2 = io_h4;
            return a0;
        }
        inline uint32_t memcmp(uint8_t *, PS2Runtime *, uint32_t a0, uint32_t a1, uint32_t a2, uint64_t &io_h2)
        {
            ++g_extCalls;
            io_h2 = 0u;
            const uint32_t n = clampSize(a2);
            if (n && (!inRam(a0, n) || !inRam(a1, n)))
            {
                giveUp();
                return 0u;
            }
            for (uint32_t i = 0; i < n; ++i)
            {
                const uint8_t x = rd<uint8_t>(a0 + i), y = rd<uint8_t>(a1 + i);
                if (x != y)
                    return static_cast<uint32_t>(static_cast<int>(x) - static_cast<int>(y));
            }
            return 0u;
        }
        inline uint32_t strlen(uint8_t *, PS2Runtime *, uint32_t a0, uint64_t &io_h2)
        {
            ++g_extCalls;
            io_h2 = 0u;
            char buf[4096];
            uint32_t len = 0;
            if (!readStr(a0, buf, sizeof(buf), len))
            {
                giveUp();
                return 0u;
            }
            return len;
        }
        inline uint32_t strcmp(uint8_t *, PS2Runtime *, uint32_t a0, uint32_t a1, uint64_t &io_h2)
        {
            ++g_extCalls;
            if (leavesOn())
            {
                uint8_t ca, cb;
                for (;; ++a0, ++a1)
                {
                    ca = rd<uint8_t>(a0);
                    cb = rd<uint8_t>(a1);
                    if (ca == 0u || ca != cb)
                        break;
                }
                return static_cast<uint32_t>(ca) - static_cast<uint32_t>(cb);
            }
            io_h2 = 0u;
            static char b1[4096], b2[4096];
            uint32_t l1 = 0, l2 = 0;
            if (!readStr(a0, b1, sizeof(b1), l1) || !readStr(a1, b2, sizeof(b2), l2))
            {
                giveUp();
                return 0u;
            }
            return static_cast<uint32_t>(::strcmp(b1, b2)); // the stub's ::strcmp
        }
        inline uint32_t getThreadId(uint8_t *ram, PS2Runtime *rt, uint64_t &io_h2)
        {
            ++g_extCalls;
            io_h2 = 0u;
#if defined(A7_OFFLINE)
            (void)ram;
            (void)rt;
            return 1u;
#else
            return static_cast<uint32_t>(decomp_sema::getThreadIdTyped(ram, rt)); // reads the scheduler only
#endif
        }
    }


    // A7: the printf family on the leg's logged memory (see the header)
    namespace a7x
    {
        inline uint32_t fmtValue(uint32_t fmt, const uint32_t *a8, uint32_t sp)
        {
            char buf[1100];
            uint32_t len = 0;
            if (fmt == 0u)
                return 0xFFFFFFFFu;
            if (!readStr(fmt, buf, 1024u, len))
            {
                giveUp();
                return 0u;
            }
            uint32_t h = 2166136261u;
            for (uint32_t i = 0; i < len; ++i)
                h = (h ^ static_cast<uint8_t>(buf[i])) * 16777619u;
            // the argument slots the stub's cursor reads, in its order (formatPs2StringCore's walk: '*' widths / precisions,
            // the length modifiers, a 64-bit value on an even slot), from the registers and then the stack above sp + 0x10
            uint32_t k = 1u; // printf's one fixed argument
            bool bad = false;
            auto slot = [&](uint32_t i) -> uint32_t {
                if (i < 8u)
                    return a8[i];
                const uint32_t at = sp + 0x10u + 4u * (i - 8u);
                if (!inRam(at, 4u))
                {
                    bad = true;
                    return 0u;
                }
                return rd<uint32_t>(at);
            };
            auto u32 = [&]() { h = (h ^ slot(k++)) * 16777619u; };
            auto u64 = [&]() {
                if (k & 1u)
                    ++k;
                u32();
                u32();
            };
            for (uint32_t i = 0; i < len;)
            {
                if (buf[i++] != '%')
                    continue;
                if (i < len && buf[i] == '%')
                {
                    ++i;
                    continue;
                }
                while (i < len && std::strchr("-+ #0", buf[i]))
                    ++i;
                if (i < len && buf[i] == '*')
                    u32(), ++i;
                else
                    while (i < len && buf[i] >= '0' && buf[i] <= '9')
                        ++i;
                if (i < len && buf[i] == '.')
                {
                    ++i;
                    if (i < len && buf[i] == '*')
                        u32(), ++i;
                    else
                        while (i < len && buf[i] >= '0' && buf[i] <= '9')
                            ++i;
                }
                bool wide = false;
                if (i < len && buf[i] == 'h')
                    i += (i + 1 < len && buf[i + 1] == 'h') ? 2u : 1u;
                else if (i < len && buf[i] == 'l')
                {
                    if (i + 1 < len && buf[i + 1] == 'l')
                        wide = true, i += 2u;
                    else
                        ++i;
                }
                else if (i < len && buf[i] == 'j')
                    wide = true, ++i;
                else if (i < len && (buf[i] == 'z' || buf[i] == 't' || buf[i] == 'L'))
                    ++i;
                if (i >= len)
                    break;
                const char c = buf[i++];
                if (std::strchr("sScpn", c))
                    u32();
                else if (std::strchr("diuxXo", c))
                    wide ? u64() : u32();
                else if (std::strchr("fFeEgGaA", c))
                    u64();
            }
            if (bad)
            {
                giveUp();
                return 0u;
            }
            return h & 0x7FFFFFFFu;
        }
        inline uint32_t printf(uint8_t *, PS2Runtime *, uint32_t a0, uint32_t a1, uint32_t a2, uint32_t a3, uint32_t t0, uint32_t t1, uint32_t t2,
                               uint32_t t3, uint32_t sp, uint64_t &io_h2)
        {
            ++g_extCalls;
            io_h2 = 0u;
            const uint32_t a8[8] = {a0, a1, a2, a3, t0, t1, t2, t3};
            return fmtValue(a0, a8, sp);
        }
        inline uint32_t iosJumpRecoverPoint(uint8_t *ram, PS2Runtime *rt, uint32_t a0, uint32_t a1, uint32_t a2, uint32_t a3, uint32_t t0, uint32_t t1,
                                            uint32_t t2, uint32_t t3, uint32_t sp, uint64_t &io_h2)
        {
            return printf(ram, rt, a0, a1, a2, a3, t0, t1, t2, t3, sp, io_h2);
        }
        inline uint32_t vsprintf(uint8_t *, PS2Runtime *, uint32_t a0, uint32_t a1, uint32_t a2, uint64_t &io_h2)
        {
            ++g_extCalls;
            io_h2 = 0u;
            char buf[1100];
            uint32_t len = 0;
            if (a1 == 0u)
                return 0xFFFFFFFFu;
            if (!readStr(a1, buf, 1024u, len) || !inRam(a0, len + 1u) || !inRam(a2, 4u))
            {
                giveUp();
                return 0u;
            }
            if (len > 255u)
                len = 255u; // the stub's kSafeVsprintfBytes
            for (uint32_t i = 0; i < len; ++i)
                wr<uint8_t>(a0 + i, static_cast<uint8_t>(buf[i] ^ static_cast<char>(rd<uint8_t>(a2) & 1u)));
            wr<uint8_t>(a0 + len, 0u);
            return len;
        }
        inline uint32_t sceWrite(uint8_t *, PS2Runtime *, uint32_t a0, uint32_t a1, uint32_t a2, uint64_t &io_h2)
        {
            ++g_extCalls;
            io_h2 = 0u;
            (void)a0;
            if (a1 >= PS2_RAM_SIZE)
                return 0xFFFFFFFFu;
            return a2 == 0u ? 0u : a2;
        }
    }

    // the reference's call of a typed runtime stub: the same version on the reference leg, the slot holder's register effects
    inline void refExt(uint32_t addr, uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime)
    {
        uint64_t h2 = a4::hi64(ctx->r[2]);
        const uint64_t h4 = a4::hi64(ctx->r[4]);
        const uint64_t a0 = Ps2GprU64(ctx, 4);
        const uint32_t a1 = Ps2GprU32(ctx, 5), a2 = Ps2GprU32(ctx, 6), a0w = Ps2GprU32(ctx, 4);
        uint64_t v0 = 0;
        switch (addr)
        {
        case 0x1283d0u: v0 = a6x::memset(rdram, runtime, a0, a1, a2, h2, h4); break;
        case 0x12821cu: v0 = a6x::memcpy(rdram, runtime, a0, a1, a2, h2, h4); break;
        case 0x128fb0u: v0 = a6x::strcpy(rdram, runtime, a0, a1, h2, h4); break;
        case 0x128e6cu: v0 = a1_sx64(a6x::strcmp(rdram, runtime, a0w, a1, h2)); break;
        case 0x128188u: v0 = a1_sx64(a6x::memcmp(rdram, runtime, a0w, a1, a2, h2)); break;
        case 0x1290c4u: v0 = a1_sx64(a6x::strlen(rdram, runtime, a0w, h2)); break;
        case 0x106ed0u: v0 = a1_sx64(a6x::getThreadId(rdram, runtime, h2)); break;
        case 0x1285c0u:
        case 0x1b3410u:
            v0 = a1_sx64(a7x::printf(rdram, runtime, a0w, a1, a2, Ps2GprU32(ctx, 7), Ps2GprU32(ctx, 8), Ps2GprU32(ctx, 9), Ps2GprU32(ctx, 10),
                                     Ps2GprU32(ctx, 11), Ps2GprU32(ctx, 29), h2));
            break;
        case 0x12c048u: v0 = a1_sx64(a7x::vsprintf(rdram, runtime, a0w, a1, a2, h2)); break;
        case 0x10b678u: v0 = a1_sx64(a7x::sceWrite(rdram, runtime, a0w, a1, a2, h2)); break;
        default: ckUnknownCall(addr); return;
        }
        ctx->r[2] = a4::mk128(h2, v0);
        ctx->pc = Ps2GprU32(ctx, 31);
    }

    // ---- A7_NCHK: a hand native against its typed function
    inline uint64_t g_nChecks = 0, g_nDiffer = 0, g_nSkipped = 0, g_nOver = 0;
    inline uint32_t g_nFirstAddr = 0;
    inline uint64_t g_nFirstV0[2] = {0, 0};
}

#define A6_BREAK(site) a7ck::legBrk(site)
#define A6_REF_BREAK() a7ck::legBrk(ctx->pc)

#if !defined(A7_OFFLINE) && PS2X_A7_CHECK
// NChk's members (the check translation unit is the one place that includes this header in a game build)
a7ck::NChk::NChk(uint32_t a, uint8_t *ram, R5900Context *c, PS2Runtime *runtime) : addr(a), rdram(ram), ctx(c)
{
    State &s = st();
    if (!ckBegin(-1, ram, runtime))
    {
        ++g_nSkipped;
        return;
    }
    ckCtx(c);
    ckMid();
    uint64_t r0 = 0;
    float rf = 0.0f;
    int k = 0;
    const bool ran = nativeLeg(a, ram, c, runtime, r0, rf, k);
    if (!ran || s.ovf)
    {
        ++g_nSkipped;
        s.active = false;
        return;
    }
    for (uint32_t i = 0; i < s.used[1]; ++i)
    {
        const uint32_t slot = s.ix[1][i];
        const uint32_t at = s.ov[1].a[slot];
        if (s.sp - at - 1u < kDeadStack)
            continue; // the dead stack: the frames below the entry sp
        if (n == kMax)
        {
            over = true;
            break;
        }
        this->a[n] = at;
        this->v[n] = s.ov[1].v[slot];
        ++n;
    }
    s.active = false;
    kind = k;
    v0 = r0;
    std::memcpy(&f0, &rf, 4);
    on = true;
}

a7ck::NChk::~NChk()
{
    if (!on || std::uncaught_exceptions())
        return;
    ++g_nChecks;
    g_nOver += over;
    bool d = false;
    if ((kind == 1 || kind == 2 || kind == 4) && Ps2GprU64(ctx, 2) != v0)
        d = true;
    if ((kind == 3 || kind == 4) && a1ck::ckBits(ctx->f[0]) != f0)
        d = true;
    for (uint32_t i = 0; i < n && !d; ++i)
        if (this->a[i] < PS2_RAM_SIZE && rdram[this->a[i]] != this->v[i])
            d = true;
    if (d)
    {
        if (!g_nDiffer)
        {
            g_nFirstAddr = addr;
            g_nFirstV0[0] = Ps2GprU64(ctx, 2);
            g_nFirstV0[1] = v0;
        }
        ++g_nDiffer;
    }
}

// the [a7] line's second half: breaks, the typed stubs, the natives' own checks (sotc_native.cpp, after a7ckReport)
void a7ckExtra(unsigned long long frame)
{
    std::fprintf(stderr, "[a7] frame %llu: breaks typed %llu, break differences %llu; typed stub calls %llu (given up %llu); natives checked %llu differ %llu "
                         "(skipped %llu, stores over the cap %llu)",
                 frame, (unsigned long long)a7ck::g_brks, (unsigned long long)a7ck::g_brkDiffer, (unsigned long long)a7ck::g_extCalls,
                 (unsigned long long)a7ck::g_extGiveUp, (unsigned long long)a7ck::g_nChecks, (unsigned long long)a7ck::g_nDiffer,
                 (unsigned long long)a7ck::g_nSkipped, (unsigned long long)a7ck::g_nOver);
    if (a7ck::g_nDiffer)
        std::fprintf(stderr, "; first native 0x%08x v0 %llx typed %llx", a7ck::g_nFirstAddr, (unsigned long long)a7ck::g_nFirstV0[0],
                     (unsigned long long)a7ck::g_nFirstV0[1]);
    std::fprintf(stderr, "\n");
}
#endif
